import "package:capp/capp.dart";

void main() {
  var app = CappManager(
    main: CappController(
      '',
      options: [CappOption(name: 'help', shortName: 'h', description: 'Show help')],
      run: (c) async {
        if (c.existsOption('help')) {
          return CappConsole(c.manager.getHelp());
        }
        return CappConsole('Hello, world!');
      },
    ),
    args: [],
    controllers: [],
  );
  app.process();
}
